from concurrent.futures import ThreadPoolExecutor

import pytest

DEFAULT_WORKERS: int = 4


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = DEFAULT_WORKERS) -> int:
    """Return the sum of square(x) for every x in xs.

    Squares are computed in a ThreadPoolExecutor with `workers` threads.
    The result must be identical for every valid worker count.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError(f"workers must be >= 1, got {workers}")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_small() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_negatives() -> None:
    assert sum_squares([-4, 4, -1]) == 33


@pytest.mark.parametrize("workers", [1, 2, 3, 8, 64])
def test_sum_squares_same_at_every_worker_count(workers: int) -> None:
    xs = list(range(-500, 500))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_sum_squares_large_input() -> None:
    xs = list(range(10_000))
    assert sum_squares(xs, workers=8) == sum(x * x for x in xs)


@pytest.mark.parametrize("workers", [0, -1])
def test_sum_squares_rejects_bad_worker_count(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=workers)


def test_sum_squares_default_workers_matches_explicit() -> None:
    xs = [3, -7, 11]
    assert sum_squares(xs) == sum_squares(xs, workers=DEFAULT_WORKERS)
